//! 👓️ Genuine heterogeneous records lend original text and numeric field owners through one object-safe source facet.
use super::*;
struct Original{text:String,count:Number,sequence:Vec<DslValue>}
impl NativeValueSource for Original{fn as_source(&self)->&dyn NativeValueSource{self}fn record_len(&self)->Result<usize,ValueError>{Ok(3)}fn record_key(&self,index:usize)->Result<super::super::NativeRecordKey<'_>,ValueError>{["text","count","sequence"].get(index).map(|key|super::super::NativeRecordKey::Name(key)).ok_or_else(invalid)}fn record_child(&self,index:usize)->Result<&dyn NativeValueSource,ValueError>{match index{0=>Ok(&self.text),1=>Ok(&self.count),2=>Ok(&self.sequence),_=>Err(invalid())}}}
#[test]fn actual_original_children_are_not_wire_proxy_owners(){let original=Original{text:"original".into(),count:Number::UInt(7),sequence:vec![DslValue::Bool(true)]};let source:&dyn NativeValueSource=&original;assert!(std::ptr::eq(source.record_child(0).unwrap().text().unwrap(),&original.text));assert_eq!(source.record_child(1).unwrap().number().unwrap(),original.count);let sequence=source.record_child(2).unwrap();assert_eq!(sequence.sequence_len().unwrap(),1);let actual=sequence.sequence_child(0).unwrap();assert!(std::ptr::eq(actual as *const dyn NativeValueSource as *const (),&original.sequence[0] as *const DslValue as *const()));assert!(actual.boolean().unwrap());assert!(source.record_child(3).is_err());}

#[test]
fn erased_original_sources_keep_typed_receivers_and_ranked_children(){
 fn receiver<T:NativeReceive<dyn NativeValueSource>>(){}
 receiver::<crate::shared_issuance::SealedShared<u64>>();receiver::<Vec<u64>>();receiver::<[u64;2]>();receiver::<semio_framework_value_persistent::list::PagedList<u64,2>>();receiver::<crate::list::persistent::PersistentList<u64>>();
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let original=DslValue::from(&row["input"]);let source:&dyn NativeValueSource=&original;let actual=if row["kind"]=="sequence"{let count=<SequenceRows as NativeSequenceInput<dyn NativeValueSource>>::length(source).unwrap();serde_json::Value::Array((0..count).map(|index|serde_json::to_value(<SequenceRows as NativeSequenceInput<dyn NativeValueSource>>::child(source,index).unwrap().number().unwrap().as_u64().unwrap()).unwrap()).collect())}else{let count=<RecordEntries as NativeSequenceInput<dyn NativeValueSource>>::length(source).unwrap();serde_json::Value::Array((0..count).map(|index|{let child=<RecordEntries as NativeSequenceInput<dyn NativeValueSource>>::child(source,index).unwrap();serde_json::json!([child.sequence_child(0).unwrap().text().unwrap(),child.sequence_child(1).unwrap().number().unwrap().as_u64().unwrap()])}).collect())};assert_eq!(actual,row["expected"]);assert_eq!(serde_json::Value::from(&original),row["input"]);}
}

#[test]
fn sequence_storage_refusal_retains_the_exact_unpublished_value(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["storage"].as_array().unwrap(){let value=row["value"].as_u64().unwrap();let index=row["index"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();let result=if row["kind"]=="vector"{let mut storage=Vec::with_capacity(row["capacity"].as_u64().unwrap()as usize);<Vec<u64>as NativeSequenceCollection<u64>>::push(&mut storage,index,value)}else{let mut storage=[None;2];if row["occupied"]==true{storage[index]=Some(3)}let before=storage;let result=<[u64;2]as NativeSequenceCollection<u64>>::push(&mut storage,index,value);if !accepted{assert_eq!(storage,before)}result};assert_eq!(result.is_ok(),accepted);if !accepted{assert_eq!(result.unwrap_err(),value)}}
}

fn original_grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn original_retire<T:RetireOwned>(value:T){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original source test retirement"));for _ in 0..10000{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();let g=original_grant(d);let(step,heap)=crate::observe_retirement_allocations(||owner.step(g).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(g));}panic!("original source retirement did not settle")}
fn receive_original<T:NativeReceive<dyn NativeValueSource>>(input:&serde_json::Value,expected:&[u64],observe:impl Fn(&T)->Vec<u64>){
 use crate::retained_clone::RetainedCloneSource;
 let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()};let original=RetainedCloneSource::admit_owned(DslValue::from(input),(),original_grant(d)).unwrap_or_else(|_|panic!("original dynamic source")).0;
 let d=T::receive_birth_demand();let g=original_grant(d);let((mut receiver,p),heap)=crate::observe_retirement_allocations(||T::begin_receive(g).unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);
 for _ in 0..10000{if receiver.output_ready(){break}let source=original.borrow().project(0,|value|value.as_source());let d=receiver.demands(source,4096).unwrap();let g=original_grant(d);for denied in [(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,grant)|active.then_some(grant)){let(step,heap)=crate::observe_retirement_allocations(||crate::owned::list_tests::receive(&mut control,denied,|control|receiver.advance(source,control,4096,denied)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(source,4096).unwrap(),d);assert_eq!(serde_json::Value::from(original.borrow().get()),*input);}let(step,heap)=crate::observe_retirement_allocations(||crate::owned::list_tests::receive(&mut control,g,|control|receiver.advance(source,control,4096,g)).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 assert!(receiver.output_ready());let d=receiver.take_demand().unwrap();let((output,p),heap)=crate::observe_retirement_allocations(||receiver.take(original_grant(d)).unwrap().unwrap());assert!(p.fits(original_grant(d)));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(observe(&output),expected);
 receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();let g=original_grant(d);let(step,heap)=crate::observe_retirement_allocations(||receiver.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(receiver.terminal_is_empty());assert_eq!(serde_json::Value::from(original.borrow().get()),*input);drop(receiver);original_retire(output);original_retire(original);
}
#[test]
fn funded_erased_sources_receive_shared_vectors_arrays_paged_and_persistent_owners(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let row=&fixture["cases"][0];let expected:Vec<u64>=serde_json::from_value(row["expected"].clone()).unwrap();let input=&row["input"];
 receive_original::<Vec<u64>>(input,&expected,|value|value.clone());
 receive_original::<[u64;2]>(input,&expected,|value|value.to_vec());
 receive_original::<semio_framework_value_persistent::list::PagedList<u64,2>>(input,&expected,|value|(0..value.len()).map(|index|u64::clone(value.get(index).unwrap())).collect());
 receive_original::<crate::list::persistent::PersistentList<u64>>(input,&expected,|value|(0..value.len()).map(|index|u64::clone(value.get(index).unwrap())).collect());
 receive_original::<crate::shared_issuance::SealedShared<u64>>(&input[0],&expected[..1],|value|vec![*value.get()]);
}
